const prev = $input.first().json;
const prepPass = (() => { try { return $('Prep Quiz Pass').first().json; } catch(e) { return null; } })();
const prepFail = (() => { try { return $('Prep Quiz Fail').first().json; } catch(e) { return null; } })();
const prep = prepPass || prepFail || {};

const list =
  prev?.search_respons?.List ||
  prev?.Response?.List ||
  prev?.Response?.Items ||
  [];

const found = list.length > 0 ? list[0] : null;
const personId = found?.Id || null;

if (!personId) {
  return [{json:{...prep, personId: null, dealId: null, skipDeal: true}}];
}

const personOwnerId = found?.OwnerId || '';
const C = prep.CONFIG;
const approvedIds = (C.OWNERS || []).map(o => o.id);

let ownerId;
if (approvedIds.includes(personOwnerId)) {
  ownerId = personOwnerId;
} else {
  ownerId = prep.ownerId || '';
}

return [{json:{...prep, personId, ownerId, skipDeal: false}}];

const prev = $input.first().json;
const prep = (() => { try { return $('Extract Person Quiz').first().json; } catch(e) { return prev; } })();
const deals = prev?.search_respons?.List || prev?.Response?.List || [];
const deal = deals.length > 0 ? (deals.find(d => d.PersonId === prep.personId) || deals[0]) : null;
const dealId = deal?.Id || null;
return [{json:{...prep, dealId, noteText: prep.noteText}}];
